#include <cstddef>
#include <iostream>
#include <vector>

struct Counts {
    std::size_t comparisons = 0;
    std::size_t shifts = 0;
};

Counts insertion_sort(std::vector<int>& values) {
    Counts counts;
    for (std::size_t i = 1; i < values.size(); ++i) {
        const int key = values[i];
        std::size_t hole = i;
        while (hole > 0) {
            ++counts.comparisons;
            if (values[hole - 1] <= key) break;
            values[hole] = values[hole - 1];
            ++counts.shifts;
            --hole;
        }
        values[hole] = key;
    }
    return counts;
}

void show(std::vector<int> values) {
    const Counts counts = insertion_sort(values);
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i > 0) std::cout << ' ';
        std::cout << values[i];
    }
    std::cout << " | comparisons=" << counts.comparisons
              << ", shifts=" << counts.shifts << '\n';
}

int main() {
    show({8, 3, 6, 3, 5});
    show({3, 5, 7, 9});
    show({9, 7, 5, 3});
    show({4, 4, 4});
}
